begin;
create temporary table sp(skey text,pack text,version_id uuid,item_id uuid,tsv uuid,pid uuid,topic text,skill text,status text,tier text) on commit drop;
insert into sp values ('apphy1-mcq-np1-008','phys1','fa8abc48-89e5-4d75-bf15-d0357b5ffd6c'::uuid,'4e8ae758-ddbf-416a-925c-c1a164b965bc'::uuid,'27111dec-ee07-48f1-86cf-1a5833dd2962'::uuid,'29c719dc-701b-470f-9e49-fab981722d3f'::uuid,'3.2','3.B','validated','4of4'),('apprecalc-mcq-015','precalc','395fa42e-514b-4f12-9e77-2f237cf2baf0'::uuid,'5a20746d-6ccf-41eb-92a9-023ca0d7b48e'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'5522b532-5e50-41f2-99a2-10144bd4e8db'::uuid,'3.2','1.B','validated','4of4'),('apprecalc-mcq-027','precalc','067e74e2-8eba-453f-8042-c26a6b2b23a7'::uuid,'c302143c-b631-4887-81ec-9b5e7a33abef'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'5522b532-5e50-41f2-99a2-10144bd4e8db'::uuid,'1.13','2.A','provisional_model','2of4'),('apprecalc-mcq-031','precalc','e90f37ad-2bc3-40ba-935d-f15edb5383f8'::uuid,'5e9d621c-c4b3-4fe0-892b-25c7aaa3e37e'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'5522b532-5e50-41f2-99a2-10144bd4e8db'::uuid,'1.2','2.A','provisional_model','2of4'),('apprecalc-mcq-037','precalc','dd33c591-f514-4ce8-9620-15597e3a93ad'::uuid,'989a3ea2-50e1-47a3-8cc3-a8d1287771cc'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'5522b532-5e50-41f2-99a2-10144bd4e8db'::uuid,'2.6','3.C','validated','4of4'),('apprecalc-mcq-040','precalc','8e1dfe66-c0ed-4ba3-b0b4-94fb48e02a60'::uuid,'69d75830-63b2-41c8-94e8-bba886ba1781'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'5522b532-5e50-41f2-99a2-10144bd4e8db'::uuid,'2.13','1.A','validated','4of4');
do $$ begin
 if exists (select 1 from sp join app.content_item_cells c on c.content_item_version_id=sp.version_id and c.skill_code is not null and c.superseded_by is null) then raise exception 'seed already has skill'; end if;
 if exists (select 1 from app.content_item_cells c where c.content_item_version_id='7c967d97-2d3f-42d1-a0e6-5460f41fdadb'::uuid and c.is_primary and c.superseded_by is null) then raise exception '015-v2 already has topic'; end if;
end $$;
create temporary table ins1 on commit drop as select sp.*, gen_random_uuid() vd from sp join app.taxonomy_cells tc on tc.taxonomy_source_version=sp.tsv and tc.topic_code=sp.topic and tc.skill_code=sp.skill;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select version_id,item_id,tsv,topic,skill,false,status,'skill_seed_tag_4voter_2026_10_03:'||tier,'skills-seed-tag-2026-10-03 (4 voters: claude-opus-5, gpt-5.5, gemini-2.5-pro, gemini-3.8-flash; validated at >=3 of 4)',null,case when status='validated' then now() end,case when status='validated' then vd end from ins1;
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
values ('7c967d97-2d3f-42d1-a0e6-5460f41fdadb'::uuid,'78d8a2d2-6b33-4132-9bd3-7195fa6601d4'::uuid,'16383753-6775-430d-960a-544cd6ee0972'::uuid,'3.2',null,true,'validated','seed_topic_tag_2026_10_03:seed_inherit','seed-topic-tag-2026-10-03 (variant vote tied 3-3; topic inherited from the seed after the seed tiebreak)',null,now(),gen_random_uuid());
create temporary table vm on commit drop as
select civ.id vversion, ci.id vitem, ci.content_key vkey, sp.tsv, sp.topic, sp.skill, sp.status, gen_random_uuid() vd
from sp join app.content_items ci on ci.exam_pack_version_id=sp.pid and ci.status='published' and ci.content_key ~* ('^'||replace(sp.skey,'-mcq-','-mcq-sv-')||'-v[0-9]+$')
join app.content_item_versions civ on civ.content_item_id=ci.id and civ.status='published'
join app.content_item_cells pc on pc.content_item_version_id=civ.id and pc.is_primary and pc.superseded_by is null and pc.topic_code=sp.topic
where sp.skey in (select skey from ins1 join (select 1) z on true)
and not exists (select 1 from app.content_item_cells c where c.content_item_version_id=civ.id and c.skill_code is not null and c.superseded_by is null);
insert into app.content_item_cells (content_item_version_id,content_item_id,taxonomy_source_version,topic_code,skill_code,is_primary,assignment_status,source,model_run_id,validated_by,validated_at,validation_decision_id)
select vversion,vitem,tsv,topic,skill,false,status,'skill_inherit_from_seed_2026_10_03:'||status,'skills-seed-tag-2026-10-03 (variant inherits its seed skill)',null,case when status='validated' then now() end,case when status='validated' then vd end from vm;
do $$ declare m text; begin select format('seeds %s; variants inheriting: %s (%s)', (select count(*) from ins1),(select count(*) from vm),(select string_agg(vkey,',') from vm)) into m; raise exception 'REHEARSAL %', m; end $$;
rollback;